     1	import type { Item } from "./insured-item.js";
     2	import { amountOwedByMhpco } from "./mhpcos-favor.js";
     3	import { insuranceValue } from "./price-list.js";
     4	
     5	export interface Damage {
     6	  itemType: string;
     7	  amount: number;
     8	}
     9	
    10	export interface Incident {
    11	  cause: string;
    12	  damages: Damage[];
    13	}
    14	
    15	export interface Policy {
    16	  insuredItems: Item[];
    17	  // How much the MHPCO may still pay out over this policy's lifetime. This is
    18	  // the single figure the MHPCO tracks per policy: opening the policy sets it
    19	  // to the full cap, and each claim depletes it. The insurance sum it is
    20	  // derived from is never reported on its own.
    21	  remainingCap: number;
    22	}
    23	
    24	export interface ClaimResult {
    25	  payout: number;
    26	  remainingCap: number;
    27	  // The policy as it stands after this claim, for settling the next one.
    28	  policy: Policy;
    29	}
    30	
    31	const DEDUCTIBLE_PER_DAMAGE = 100;
    32	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    33	
    34	// The MHPCO insures a policy for the sum of its items' insurance values.
    35	function insuranceSum(insuredItems: Item[]): number {
    36	  return insuredItems
    37	    .map(insuranceValue)
    38	    .reduce((sum, value) => sum + value, 0);
    39	}
    40	
    41	// The MHPCO pays out at most twice the insurance sum over a policy's lifetime.
    42	// A policy is opened with that whole cap intact; each claim depletes it.
    43	export function openPolicy(insuredItems: Item[]): Policy {
    44	  return {
    45	    insuredItems,
    46	    remainingCap: insuranceSum(insuredItems) * CAP_MULTIPLE_OF_INSURANCE_SUM,
    47	  };
    48	}
    49	
    50	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
    51	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
    52	const FULL_REIMBURSEMENT_RATE = 1;
    53	
    54	// A damage entry names only the type of the item it befell, so the MHPCO can
    55	// identify the damaged item no further than the policy's first insured item of
    56	// that type. Where a policy covers several alike items this is a deliberate
    57	// approximation: alike items share the traits the reimbursement clauses read,
    58	// so any of them yields the same clause. Counting damage entries against the
    59	// insured items of their type -- and rejecting an excess -- is a separate rule
    60	// the MHPCO has not yet put into force.
    61	function firstInsuredItemOfType(
    62	  policy: Policy,
    63	  damage: Damage,
    64	): Item | undefined {
    65	  return policy.insuredItems.find((item) => item.type === damage.itemType);
    66	}
    67	
    68	function isHighlyEnchanted(item: Item): boolean {
    69	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
    70	}
    71	
    72	// Which reimbursement clause covers the damaged item. Damage to a highly
    73	// enchanted item is reimbursed at half; all other damage in full.
    74	// The dragon-material clause is subsumed by that default: it reimburses in
    75	// full, and where it meets the high-enchantment clause the 50 % rate wins, so
    76	// it never changes a payout and needs no branch of its own.
    77	// An item the policy does not list has no clause and is reimbursed in full --
    78	// rejecting such a damage entry is a separate, not yet implemented rule.
    79	function reimbursementRateFor(item: Item | undefined): number {
    80	  if (item !== undefined && isHighlyEnchanted(item)) {
    81	    return HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
    82	  }
    83	  return FULL_REIMBURSEMENT_RATE;
    84	}
    85	
    86	// The MHPCO settles each damage event separately: it reimburses the damage
    87	// under the applicable clause, then withholds its deductible once per event.
    88	function settlementForDamageEvent(policy: Policy, damage: Damage): number {
    89	  const rate = reimbursementRateFor(firstInsuredItemOfType(policy, damage));
    90	  return damage.amount * rate - DEDUCTIBLE_PER_DAMAGE;
    91	}
    92	
    93	// What the MHPCO owes for the whole incident before rounding: every damage
    94	// event settled under its clause, reduced to what the policy's lifetime cap
    95	// still allows.
    96	function cappedSettlement(policy: Policy, incident: Incident): number {
    97	  const settled = incident.damages
    98	    .map((damage) => settlementForDamageEvent(policy, damage))
    99	    .reduce((sum, amount) => sum + amount, 0);
   100	  return Math.min(settled, policy.remainingCap);
   101	}
   102	
   103	export function claim(policy: Policy, incident: Incident): ClaimResult {
   104	  // A payout is owed by the MHPCO, so its fraction is rounded down. Only this
   105	  // final amount is rounded; the settlement above stays fractional. Rounding
   106	  // last is safe for a capped claim too: the cap is always a whole number of
   107	  // G, so rounding a capped settlement changes nothing.
   108	  const payout = amountOwedByMhpco(cappedSettlement(policy, incident));
   109	  const remainingCap = policy.remainingCap - payout;
   110	  return { payout, remainingCap, policy: { ...policy, remainingCap } };
   111	}
